function drawGeometricPanel(p: any, layer: Layer): void {
  const q = layer.params;
  const layout = panelLayout(Boolean(q.tight));
  withNativeScale(p, () => {
    p.background(...colour(layer.palette, 4));
    p.noStroke();
    p.fill(...colour(layer.palette, 0));
    p.rect(45, 45, 630, 630);
