  withNativeScale(p, () => {
    p.background(...colour(layer.palette, 4));
    p.noStroke();
    p.fill(...colour(layer.palette, 4), 28);
    p.circle(304, 340, 125);
    p.circle(422, 286, 98);
    p.circle(387, 448, 150);
    p.noFill();
