      const path = layout.paths[index];
      const color = colour(layer.palette, path.colorIndex);
      if (q.brush === "beads") {
        p.noStroke();
        p.fill(...color, 175);
        for (let point = 0; point < path.points.length; point += 5) p.circle(...path.points[point], 2.5 + (index % 3));
